Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.

(* [comment removed for export] *)
Ltac live_sub_tac ::=
  let e := fresh "e" in let He := fresh "He" in intros e He;
  try solve [destruct He];
  first [ match goal with S : forall x, In x ?l -> In x ?l' |- In _ ?l' => lazymatch type of He with In _ l => exact (S _ He) end end
        | repeat match goal with H : rt_live _ _ = _ |- _ => rewrite H in * end;
          repeat first [ exact He
                       | match goal with S : forall x, In x ?l -> In x ?l' |- In _ ?l' => lazymatch type of He with In _ l => exact (S _ He) end end
                       | right
                       | apply live_remove_sub in He ] ].

(* [comment removed for export] *)
Ltac mbn sl :=
  repeat match goal with
  | |- context [sx32 (Z_to_bv 64 ?z)] => rewrite (sx32_small z) by sl
  | |- context [bv_unsigned (Z_to_bv 64 ?z)] => rewrite (unsigned_lit z) by sl
  | |- context [bv_swrap 32 ?z] => rewrite (bv_swrap_small 32 z) by (change (bv_half_modulus 32) with (2^31); sl)
  | |- context [?z mod 18446744073709551616] => rewrite (Z.mod_small z 18446744073709551616) by sl
  end.
Ltac mbn_in H sl :=
  repeat match type of H with
  | context [sx32 (Z_to_bv 64 ?z)] => rewrite (sx32_small z) in H by sl
  | context [bv_unsigned (Z_to_bv 64 ?z)] => rewrite (unsigned_lit z) in H by sl
  | context [bv_swrap 32 ?z] => rewrite (bv_swrap_small 32 z) in H by (change (bv_half_modulus 32) with (2^31); sl)
  | context [?z mod 18446744073709551616] => rewrite (Z.mod_small z 18446744073709551616) in H by sl
  end.

Section MBORD.
Variable RT : rt_sig.
Hypothesis AF : art_facts RT.
Hypothesis GP : rt_gaps RT.
Hypothesis FKC : rt_fk_contracts RT.
Hypothesis PABG : pixAddBorderGeneral0_cps2R RT.
Hypothesis PROP : pixRasterop_cps2A RT.
Hypothesis PROPN : pixRasterop_null_cps2 RT.

